// 1. React 路由懒加载（Vite / Webpack 均适用）
import { lazy, Suspense } from 'react';
import { Routes, Route } from 'react-router-dom';

// 每个路由对应一个独立 chunk，contenthash 命名
const Home = lazy(() => import(/* webpackChunkName: "home" */ './pages/Home'));
const About = lazy(() => import(/* webpackChunkName: "about" */ './pages/About'));
const Dashboard = lazy(() => import(/* webpackPrefetch: true */ './pages/Dashboard'));

function App() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
        <Route path="/dashboard" element={<Dashboard />} />
      </Routes>
    </Suspense>
  );
}

// 2. Webpack SplitChunksPlugin 配置
// webpack.config.js
module.exports = {
  optimization: {
    splitChunks: {
      chunks: 'all',           // 同步和异步 chunk 都分割
      minSize: 20000,          // 模块 > 20KB 才提取
      minChunks: 1,            // 被 1 个以上 chunk 引用就提取
      cacheGroups: {
        vendors: {
          test: /[\/]node_modules[\/]/,
          name: 'vendors',
          priority: -10,       // 优先级，数字大优先
          chunks: 'all',
        },
        common: {
          minChunks: 2,        // 至少 2 个 chunk 共用才提取
          name: 'common',
          priority: -20,
          reuseExistingChunk: true, // 已有 chunk 包含该模块则复用
        },
      },
    },
  },
  output: {
    filename: '[name].[contenthash:8].js',
    chunkFilename: '[name].[contenthash:8].js', // 异步 chunk 命名
  },
};
